output_text:
[
  {
    "id": "take_cart_at_depot",
    "text": "Customers are obliged to pick up the available cart at the cart depot before doing their shopping.",
    "abstraction": {
      "state_properties": {
        "cart_depot": "at(1,5)",
        "cart_available_at_depot": "cartAt(1,5)"
      },
      "events": {
        "pickup_cart_at_depot": {
          "pre": {
            "and": [
              "cart_depot",
              "cart_available_at_depot",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_cart_at_depot"
    }
  },
  {
    "id": "no_bypass_cart_depot",
    "text": "A customer must not walk east past the cart depot while the depot cart is still there and they do not have it.",
    "abstraction": {
      "state_properties": {
        "cart_depot": "at(1,5)",
        "without_cart": {
          "not": "hasCart"
        },
        "cart_still_at_depot": "cartAt(1,5)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_depot",
          "cart_still_at_depot",
          "without_cart",
          "E"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Items should not be carried by hand inside the supermarket; they should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A customer may pick up shelf items only while in possession of the shopping cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_item",
    "text": "After any item has been collected into the cart, the cart must eventually be returned at the counter cell before leaving.",
    "abstraction": {
      "state_properties": {
        "counter_cell": "at(0,1)"
      },
      "events": {
        "item_collected_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_at_counter": {
          "pre": {
            "and": [
              "counter_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_collected_with_cart",
      "discharge": "return_cart_at_counter"
    }
  },
  {
    "id": "leave_cart_only_at_counter",
    "text": "A cart may be put down only at the designated counter location at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "counter_cell": "at(0,1)",
        "not_counter_cell": {
          "not": "counter_cell"
        }
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          "not_counter_cell"
        ]
      }
    }
  },
  {
    "id": "exit_only_on_foot",
    "text": "Customers must exit on foot, without still pushing the cart or carrying items by hand.",
    "abstraction": {
      "state_properties": {
        "encumbered": {
          "or": [
            "hasCart",
            "handFull"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "encumbered"
        ]
      }
    }
  },
  {
    "id": "no_cart_into_right_lower_aisle",
    "text": "Carts are not allowed to continue into the lower-right aisle beyond the egg shelf, so from cell (6,4) a cart must not be pushed east or south.",
    "abstraction": {
      "state_properties": {
        "egg_shelf_end": "at(6,4)",
        "restricted_lower_right_cells": {
          "or": [
            "at(7,4)",
            "at(8,4)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushing_cart",
          {
            "or": [
              {
                "and": [
                  "egg_shelf_end",
                  {
                    "or": [
                      "E",
                      "S"
                    ]
                  }
                ]
              },
              "restricted_lower_right_cells"
            ]
          }
        ]
      }
    }
  }
]
